-- Read-only incremental verification. 09_verify.sql describes the original ERD baseline.
SELECT TABLE_NAME FROM USER_TABLES WHERE TABLE_NAME IN ('FACILITY_BLOCK','TBL_FACILITY_BLOCK_LOG') ORDER BY TABLE_NAME;
SELECT SEQUENCE_NAME FROM USER_SEQUENCES WHERE SEQUENCE_NAME='SEQ_FACILITY_BLOCK_LOG';
SELECT COLUMN_NAME,DATA_TYPE,NULLABLE FROM USER_TAB_COLUMNS WHERE TABLE_NAME='FACILITY_BLOCK' AND COLUMN_NAME IN ('ENABLED_YN','CANCELLED_AT','CANCELLED_BY','CANCEL_REASON') ORDER BY COLUMN_ID;
SELECT CONSTRAINT_NAME,STATUS FROM USER_CONSTRAINTS WHERE TABLE_NAME IN ('FACILITY_BLOCK','TBL_FACILITY_BLOCK_LOG') ORDER BY TABLE_NAME,CONSTRAINT_NAME;
SELECT ENABLED_YN,COUNT(*) BLOCK_COUNT FROM FACILITY_BLOCK GROUP BY ENABLED_YN;
SELECT ACTION_CODE,COUNT(*) LOG_COUNT FROM TBL_FACILITY_BLOCK_LOG GROUP BY ACTION_CODE;
